-- Offline operating receipts remain separate from trust custody and provider evidence.
CREATE TABLE s_billing_money_revision(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL);
INSERT INTO s_billing_money_revision VALUES(1,0);
CREATE TABLE s_billing_requests(request_key TEXT PRIMARY KEY,kind TEXT NOT NULL,fingerprint TEXT NOT NULL,result_id TEXT NOT NULL);
CREATE TABLE s_billing_receipts(id TEXT PRIMARY KEY,source_matter_id TEXT NOT NULL REFERENCES s_matters(id),payer TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN('cash','check','wire','ach')),reference TEXT NOT NULL,received_date TEXT NOT NULL,deposit_date TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES s_trust_accounts(id),cents INTEGER NOT NULL CHECK(cents>0),actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE s_billing_allocations(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL REFERENCES s_billing_receipts(id),bill_id TEXT NOT NULL REFERENCES s_bills(id),cents INTEGER NOT NULL CHECK(cents>0),earned_cents INTEGER NOT NULL CHECK(earned_cents>=0),tax_cents INTEGER NOT NULL CHECK(tax_cents>=0),effective_date TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL,CHECK(cents=earned_cents+tax_cents));
CREATE INDEX s_billing_allocations_bill ON s_billing_allocations(bill_id);
CREATE TABLE s_billing_receipt_reversals(id TEXT PRIMARY KEY,receipt_id TEXT NOT NULL UNIQUE REFERENCES s_billing_receipts(id),effective_date TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TABLE s_billing_writeoffs(id TEXT PRIMARY KEY,bill_id TEXT NOT NULL REFERENCES s_bills(id),cents INTEGER NOT NULL CHECK(cents>0),earned_cents INTEGER NOT NULL CHECK(earned_cents>=0),tax_cents INTEGER NOT NULL CHECK(tax_cents>=0),effective_date TEXT NOT NULL,reason TEXT NOT NULL,requested_by TEXT NOT NULL,at TEXT NOT NULL,CHECK(cents=earned_cents+tax_cents));
CREATE TABLE s_billing_writeoff_decisions(writeoff_id TEXT PRIMARY KEY REFERENCES s_billing_writeoffs(id),actor TEXT NOT NULL,at TEXT NOT NULL);
CREATE TRIGGER s_billing_requests_no_update BEFORE UPDATE ON s_billing_requests BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_requests_no_delete BEFORE DELETE ON s_billing_requests BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_receipts_no_update BEFORE UPDATE ON s_billing_receipts BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_receipts_no_delete BEFORE DELETE ON s_billing_receipts BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_allocations_no_update BEFORE UPDATE ON s_billing_allocations BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_allocations_no_delete BEFORE DELETE ON s_billing_allocations BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_receipt_reversals_no_update BEFORE UPDATE ON s_billing_receipt_reversals BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_receipt_reversals_no_delete BEFORE DELETE ON s_billing_receipt_reversals BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_writeoffs_no_update BEFORE UPDATE ON s_billing_writeoffs BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_writeoffs_no_delete BEFORE DELETE ON s_billing_writeoffs BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_writeoff_decisions_no_update BEFORE UPDATE ON s_billing_writeoff_decisions BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_writeoff_decisions_no_delete BEFORE DELETE ON s_billing_writeoff_decisions BEGIN SELECT RAISE(ABORT,'posted billing records are append-only'); END;
CREATE TRIGGER s_billing_allocations_money_revision AFTER INSERT ON s_billing_allocations BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_billing_receipt_reversals_money_revision AFTER INSERT ON s_billing_receipt_reversals BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_billing_writeoff_decisions_money_revision AFTER INSERT ON s_billing_writeoff_decisions BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_operating_payments_money_revision AFTER INSERT ON s_operating_payments BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_operating_payment_reversals_money_revision AFTER INSERT ON s_operating_payment_reversals BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_trust_transfers_money_revision AFTER INSERT ON s_trust_transfers BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_trust_transfer_actions_money_revision AFTER INSERT ON s_trust_transfer_actions BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_bill_tax_approvals_money_revision AFTER INSERT ON s_bill_tax_approvals BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER s_bills_money_revision AFTER UPDATE ON s_bills BEGIN UPDATE s_billing_money_revision SET revision=revision+1 WHERE id=1; END;
